retained_functions.diffcells:
def diffcells():
    b=previous_frame.ascii.split('\n'); a=current_frame.ascii.split('\n')
    from collections import defaultdict
    g=defaultdict(list)
    for rr in range(1,64):
        for cc in range(64):
            if b[rr][cc]!=a[rr][cc]: g[(b[rr][cc],a[rr][cc])].append((rr,cc))
    out={}
    for k,v in g.items():
        rs=[p[0] for p in v]; cs=[p[1] for p in v]
        out[k]=(len(v),(min(rs),min(cs),max(rs),max(cs)))
    return out

retained_functions.read_state:
def read_state(fr):
    a=fr.ascii.split('\n')
    seg=fr.segmentation
    dia=[];sq={}
    for n in seg['nodes']:
        b=n['boundary']; rs=[p[0] for p in b]; cs=[p[1] for p in b]
        r0,c0,r1,c1=min(rs),min(cs),max(rs),max(cs)
        ctr=((r0+r1)//2,(c0+c1)//2)
        if n['pixels'] in (12,13) and n['color'] in ('W','G') and (r1-r0)==4:
            dia.append((n['color'],ctr))
        if n['pixels']==20: sq[n['color']]=ctr
    return dia,sq

