def sq_centers(fr):
    g=getgrid(fr)
    out=set()
    for r in range(1,63):
        for c in range(1,63):
            if g[r][c]=='M':
                nb=sum(1 for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)) if g[r+dr][c+dc]!='B')
                if nb>=3: out.add((r,c))
